INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('a8a1d3ded9f046ea82bff87e71b4509d','反共誓约惨案','河北','沧州','河北 沧州',0,8,'伪职：伪任丘县县长；策划臭名昭著的反共誓约惨案，逼迫群众宣誓反共，残害大量平民百姓。；结局：1945 年公审判处死刑','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('0abdf8672be84b75bcc8c20a1bb900a7','杨湾惨案','安徽','安庆','安徽 安庆',0,2,'伪职：望江县杨湾汉奸向导；罪行：带领日军汽艇扫荡杨湾，直接酿成杨湾惨案，52 名平民惨遭杀害，村庄焚毁，为日军打探乡间抗日武装踪迹望江新闻网。；结局：抗战胜利公审处决。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('e820b44fcacf46a2b0a92995d70fd127','黄土桥惨案','江苏','淮安','江苏 淮安',0,2,'伪职：伪淮安县警察大队长；罪行：沙贵章副手，执掌伪警察武装，参与黄土桥惨案，下乡扫荡，抓捕酷刑迫害爱国群众。；结局：抗战胜利后公审枪决。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('5f839da585c54ca3b19a05bdaa9ea114','万章惨案','山西','晋城','山西 晋城',0,2,'伪职：原国民党二区区长，日伪咨议员；罪行：被峰头据点抓捕随即叛变；出卖万章村民兵情报，直接酿成万章惨案，多名民兵牺牲。；结局：万章村公审就地枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('0b29250023a24153b4b9f307e95531fa','三十二烈士惨案','黑龙江','大庆','黑龙江 大庆',0,1,'伪职：抗日救国会叛徒；罪行：出卖三肇地下党组织，泄露地下机关地点、救国会人员名册，直接引发三肇大搜捕，造成三十二烈士惨案，大批地下党员被捕牺牲抖音百科。；结局：解放后镇压反革命公审处决。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('63910bd95912469998463dc997005e1d','下五家子惨案','','','',0,1,'伪职：伪锦西县伪县长；罪行：伪满正式建制后的锦西县主官；推行保甲连坐，强征劳工粮食，配合日伪对虹螺岘、缸窑岭山区义勇军进行讨伐，参与下五家子惨案相关治安部署。；结局：光复后汉奸罪判刑。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('d08c5880f87b43dab991d61f9c16746e','东张万人坑惨案','','','',0,1,'伪职：伪浮山县县长；罪行：建立浮山伪政权，设立新民会、剿共委员会，制造东张万人坑惨案，残害大量百姓临汾新闻网。；结局：县城收复后逮捕判刑','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('154686dd84b24696a9aa80bdac7250a1','亳二区惨案','安徽','亳州','安徽 亳州',0,2,'伪职：白枪会头目，勾结日伪；罪行：地方会道门武装，勾结日伪发动暴乱，制造亳二区惨案，杀害 9 名党员干部，抓捕二十余名革命人员。；结局：暴乱被镇压，捕获后公审枪决。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('9c904051c5824930aa52d3eecd211478','令公庙惨案','江西','南昌','江西 南昌',0,1,'伪职：汉奸向导；罪行：1942年令公庙大屠杀带路元凶，带领日军制造860余人惨死的惨案；结局：战后被依法处决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('22e8b92295a545e3b6d2311e1f49cb46','十八人被杀惨案','安徽','池州','安徽 池州',0,1,'伪职：贵池伪特务；罪行：和章荣高互相争斗，肆意株连平民，酿成十八人被杀惨案。；结局：肃奸逮捕，判处重刑。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('562ccb47a8864f458561f8e57359591f','厚和大惨案','内蒙古','呼和浩特','内蒙古 呼和浩特',0,7,'伪职：学生叛徒；1940 告密出卖绥蒙各界抗日救国会，制造厚和大惨案，190 多人被捕，百余人惨死，地下组织遭到毁灭性破坏，出卖刘洪雄等革命志士。；结局：抗战胜利后公审枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('32959b0404054be582429673b8d86273','后马家村惨案','山西','吕梁','山西 吕梁',0,1,'伪职：伪离石警察所长；罪行：掌管伪警察，指挥便衣，严刑拷打被捕抗日人员，递送情报配合进山扫荡，制造后马家村惨案。；结局：解放后公审枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('643440a92f0a4fb785279c12427561a8','四十二人惨案','安徽','池州','安徽 池州',0,1,'伪职：伪区特务头目；罪行：铁杆特务，因索贿未遂，随意抓捕杜祖汉等 42 名无辜百姓，押至贵池三阳墩集体屠杀，制造四十二人惨案。；结局：1950 年捉拿归案公审枪决。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('5500013dd4de4bd496ba1924b68aab0a','大华饭店大轰炸惨案','江苏','镇江','江苏 镇江',0,1,'伪任职务：潜伏汉奸，架设秘密电台；使用镜子反光为日机轰炸镇江做地面指引，造成大华饭店大轰炸惨案金山网。。结局：当场抓获，江边就地枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('36550fd17b9b4a47b99146e625852089','大胡庄惨案','江苏','淮安','江苏 淮安',0,1,'伪职：日伪密探（篾匠）；罪行：以走街串巷编织竹器为掩护搜集情报；告密新四军驻地，直接引发大胡庄惨案，致使大量指战员牺牲。；结局：解放后清算镇压。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('8724418cd9b64fd7974d894614c626b9','大西庄惨案','山西','阳泉','山西 阳泉',0,2,'伪职：伪警备队第二中队长，驻守河底据点；罪行：带队下乡扫荡，制造大西庄惨案，残害地道内避难百姓。；结局：解放后公审枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('9ae3fe310f31448cb2e1ee6ac068a308','安东教育救国会惨案','辽宁','大连','辽宁 大连',0,1,'伪职：伪安东省教育厅厅长；罪行：“安东教育救国会惨案” 之后到任；清洗爱国师生，强力推行奴化教育；后升任伪满总务厅次长、民生部大臣，主导鸦片政策。；结局：抚顺战犯管理所关押，后期特赦抖音百科。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('2640eced6d6744309433d77a0b6c970b','平顶山惨案','','','',0,1,'伪职：伪抚顺县早期县长；罪行：九一八后投敌，组建抚顺县伪公署；平顶山惨案发生时，向伪奉天省报告情况，配合日军统治。；结局：抗战胜利逮捕，汉奸罪判刑。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('1f407d47da9442a190cc020fd8fed992','建昌药王庙惨案','辽宁','葫芦岛','辽宁 葫芦岛',0,1,'伪职：伪凌南县（建昌前身）县长；罪行：建昌药王庙惨案发生时伪县长；配合日军扫荡，抓捕、杀害大量抗日志士与群众。；结局：光复后汉奸罪判刑。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('4b8a46e4b6194525a159d9629727b724','归还兵惨案','内蒙古','通辽','内蒙古 通辽',0,4,'伪职：伪兴安南警备军副官处长；参与策划 “归还兵惨案”，诱骗起义蒙古武装，协助日军解除武装、屠杀起义官兵。；结局：解放后镇反公审枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('62a27645f6bc4efd91d961e57be5e5a0','成安惨案','河北','邯郸','河北 邯郸',0,4,'伪职：伪成安县县长；成安惨案之后接管伪政权，协助日军维持占领秩序，搜刮物资。；结局：抗战胜利后逮捕判刑','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('0a682809d85b49598a039ceb6623e966','捡门惨案','江西','南昌','江西 南昌',0,1,'伪职：日军靖安队头目；罪行：充当日军向导，制造华盐桥、捡门惨案；结局：暂无明确结局记载','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('f0bba79abf444dd18c369d6e7bb2f942','无人区惨案','','','',0,4,'伪职：伪赤城县县长；执行集家并村，逼迫百姓迁入人圈，制造无人区惨案。；结局：日本投降后潜逃，1946 抓捕归案判刑','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('1678a6e589534031a2ec2e81433e7be5','朔县惨案','山西','朔州','山西 朔州',0,2,'伪职：商会会长，朔县惨案中告密汉奸；罪行：城破当众指认抗日县长郭同仁，致使郭同仁被日军烧死；后被日军杀死，未等到战后审判。；结局：被日军刺死','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('4dab44de77aa4f11a9a2dd18adaedbda','本溪胡家村惨案','黑龙江','哈尔滨','黑龙江 哈尔滨',0,1,'伪职：伪哈尔滨警察厅刑事科搜查股长（“白菜叶” 之一）；罪行：制造本溪胡家村惨案，200 余群众被捕屠杀；追踪捕杀抗日志士，严刑逼供杀害多人。；结局：1951 年处决。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('0c6a68df4af648ad93bfc8bcba411977','桑矾救国会惨案','河北','张家口','河北 张家口',0,6,'伪职：联庄会头目，后投敌；制造桑矾救国会惨案，杀害我方干部，逮捕大批救国会人员送交日军，严重破坏宣涿怀根据地。；结局：怀来解放后公审枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('04601cb4aee744e9b95c6a08323f7930','民间惨案','安徽','安庆','安徽 安庆',0,1,'伪职：月山据点便衣特务；罪行：先投靠日军当情报特务，后又摇摆向国民党；日军为抓捕他扑空叶家享堂，迁怒无辜平民，酿成民间惨案中安在线。；结局：被我方武工队追踪击毙。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('597632a7d512467f830fc66ad08d6647','泊里大屠杀惨案','山东','潍坊','山东 潍坊',0,1,'伪任职务：伪滨海警备军司令，盘踞泊里，制造泊里大屠杀惨案。结局：1944 年病死于青岛','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('8c2df81191fb44329b019b82e29d766c','洪山惨案','湖南','岳阳','湖南 岳阳',0,1,'伪任职务：岳阳伪警察巡官，洪山惨案主要凶手，亲手残害多名百姓。结局：抗战胜利公审处决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('f691618172a542b38a282259f8951e20','潘家峪惨案','河北','','河北',0,5,'伪职：伪丰润县县长，兼警备大队长、新民会会长；参与策划潘家峪惨案，部署全县扫荡，强征粮款民夫资敌。；结局：抗战胜利公审判处死刑','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('0c9d8fe641a14b97a302cf206c4bcc3e','玉田大抓捕惨案','河北','','河北',0,6,'伪职：伪玉田县县长；配合日军铃木启久，推行第四次治安强化运动；组建反共自卫团、棍儿团，炮制八大杀禁律，一周抓捕三千余抗日人员，制造玉田大抓捕惨案唐山党史网。；结局：冀东民主政府公审死刑','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('decff296f2fc4401a9650ed7e1ffd26f','王厂沟惨案','河北','承德','河北 承德',0,5,'伪职：伪满讨伐队头目，龙须门讨伐队；参与王厂沟惨案，屠杀平民 49 人、八路军干部战士多人，在承德??青龙??兴隆疯狂讨伐扫荡。；结局：1946??03??13 承德特别法庭公审枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('af6c951653e54a1eaa6e05e2a442d27e','白家辛庄惨案','山西','朔州','山西 朔州',0,2,'伪职：五地委秘书叛变，大特务；罪行：核心叛徒，出卖情报酿成白家辛庄惨案，168 名抗日干部学员遇难，是雁北重大惨案祸首之一。；结局：解放后公审枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('f4fabdbc75a740b1a79a289b4728df0f','石洞惨案','安徽','六安','安徽 六安',0,1,'伪职：霍山便衣汉奸；罪行：带路日军扫荡大河厂，砍断电话线嫁祸乡民，酿成石洞全家 13 口被炸死惨案，烧杀劫掠乡村。；结局：霍山地方武装捕获正法。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('416db1709be546af8eefd5b6d00d7efe','范家湾惨案','安徽','铜陵','安徽 铜陵',0,1,'伪职：顺安特务大队长（双料特务）；罪行：伪装进步骗取皖南行署参议员身份，公开叛变投敌；出卖地下党组织，抓捕杀害督导处主任陈益卿；勾结中统，组建特务武装；向日军告密直接酿成范家湾惨案，致使巫希权等 28 位新四军指战员牺牲。；结局：抗战胜利后肃奸捕获，判处死刑处决。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('92c99293d0d94837a884dd9b0b0590a1','起义警察惨案','内蒙古','通辽','内蒙古 通辽',0,5,'伪职：伪扎鲁特旗警务科长；假意参加起义，出卖加林台等人，直接制造起义警察惨案，双手沾满鲜血。；结局：1945 年光复后公审枪决','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('c6d0a6d47dfb42619deb08ab017f31e8','门楼下惨案','江苏','无锡','江苏 无锡',0,1,'伪职：伪乡长兼清乡大队长；罪行：向日军告密新四军驻地情报，直接引发门楼下惨案，致使日军奔袭扫荡，残害百姓无锡市档案...。；结局：抗战胜利后公审处决。','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('5e29f9f02b1942f8a9b4be3eef090154','雒贵琦惨案','山西','吕梁','山西 吕梁',0,1,'伪职：石门墕据点伪维持会总头目；罪行：土豪劣绅投敌；盘踞石门墕据点，抓捕、悬赏缉拿我方干部；引日伪军制造雒贵琦惨案，残害大批抗日军民。；结局：武工队锄奸击毙','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
INSERT INTO `atrocitycases` (`Id`,`Name`,`Province`,`City`,`Location`,`IsGeneral`,`PersonCount`,`Summary`,`CreatedAt`,`UpdatedAt`) VALUES ('5bb5c0d8d13041b9a0099e2edd7640c6','（通用描述）制造多起惨案','山东','济宁','山东 济宁',1,88,'伪职：伪兴隆县县长；强力推行集家并村，强修人圈，疯狂清剿雾灵山抗日根据地，制造多起惨案。；结局：1945 被俘，公审判处死刑','2026-09-10 15:15:11.963723','2026-09-10 15:15:11.963723');
